// Generates the design system styles from design-system/ (the single source for everything visual):
//   src/styles/tokens.scss  CSS custom properties named exactly as in tokens.json, plus the type styles
//   src/styles/bundle.css   components/bundle.css without the Google Fonts @import (fonts are self-hosted)
// Both files are generated and git-ignored. Do not edit them, change design-system/ instead.
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const designSystem = new URL('../../design-system/', import.meta.url);
const outDir = new URL('../src/styles/', import.meta.url);
const tokens = JSON.parse(readFileSync(new URL('tokens.json', designSystem), 'utf8'));
const header = '/* GENERATED by scripts/tokens.mjs from design-system/. Do not edit. */\n';

const alias = (value) => {
  const match = /^\{([\w-]+)\}$/.exec(value);
  return match ? `var(--${match[1]})` : value;
};

const light = [];
const dark = [];
const defined = new Set();

function themed(token) {
  defined.add(token.name);
  if (typeof token.value === 'string') {
    light.push([token.name, alias(token.value)]);
    return;
  }
  light.push([token.name, alias(token.value.light)]);
  if (token.value.dark !== undefined) dark.push([token.name, alias(token.value.dark)]);
}

for (const token of tokens.color.tokens) themed(token);
for (const family of ['spacing', 'radius', 'shadow', 'border', 'size']) {
  for (const token of tokens[family].tokens) themed(token);
}
for (const [name, value] of Object.entries(tokens.type.families)) {
  defined.add(`font-${name}`);
  light.push([`font-${name}`, value]);
}

const block = (selector, entries, scheme) =>
  `${selector} {\n  color-scheme: ${scheme};\n${entries.map(([n, v]) => `  --${n}: ${v};`).join('\n')}\n}\n`;

let css =
  header + block(':root', light, 'light') + '\n' + block(':root[data-theme="dark"]', dark, 'dark');

// Type styles as utility classes: .mcg-type-<name>
css += '\n';
for (const group of tokens.type.groups) {
  for (const style of group.styles) {
    const family = style.family ?? group.family;
    const rules = [
      `font-family: var(--font-${family})`,
      `font-size: ${style.fontSize}`,
      `line-height: ${style.lineHeight}`,
      `font-weight: ${style.fontWeight}`,
      style.letterSpacing ? `letter-spacing: ${style.letterSpacing}` : null,
    ].filter(Boolean);
    css += `.mcg-type-${style.name} { ${rules.join('; ')}; }\n`;
  }
}

// bundle.css: drop the @import of Google Fonts (GDPR, CSP) and check that every token it uses exists.
const bundle = readFileSync(new URL('components/bundle.css', designSystem), 'utf8')
  .split('\n')
  .filter((line) => !/^@import\s+url\(/.test(line))
  .join('\n');
const localProperties = new Set(['person']); // set inline by the PersonCard
const missing = [...new Set([...bundle.matchAll(/var\(--([\w-]+)\)/g)].map((m) => m[1]))].filter(
  (name) => !defined.has(name) && !localProperties.has(name),
);
if (missing.length > 0) {
  console.error(`bundle.css uses tokens that are not in tokens.json: ${missing.join(', ')}`);
  process.exit(1);
}

mkdirSync(outDir, { recursive: true });
writeFileSync(new URL('tokens.scss', outDir), css);
writeFileSync(new URL('bundle.css', outDir), header + bundle);
console.log(
  `tokens: ${defined.size} custom properties -> ${fileURLToPath(new URL('tokens.scss', outDir))}`,
);
